--
-- Base de datos: `agencia_estatal`
--

DELIMITER $$
--
-- Funciones
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_dias_habiles` (`fecha_ini` DATE, `dias_a_sumar` INT) RETURNS DATE DETERMINISTIC begin
    declare dias int default 0;
    declare fecha_temp date;
    declare es_festivo boolean default false;
    declare mes_f int;
    declare dia_f int;
    declare dia_sem int;
    
    set fecha_temp = fecha_ini;
    
    while dias < dias_a_sumar do
        set fecha_temp = date_add(fecha_temp, interval 1 day);
        set dia_sem = dayofweek(fecha_temp);
        set mes_f = month(fecha_temp);
        set dia_f = day(fecha_temp);
        set es_festivo = false;
        
        if dia_sem not in (1, 7) then
            if (mes_f = 1 and dia_f = 1) or
               (mes_f = 5 and dia_f = 1) or
               (mes_f = 9 and dia_f = 16) or
               (mes_f = 12 and dia_f = 25) then
                set es_festivo = true;
            end if;
            
            if dia_sem = 2 then
                if mes_f = 2 and dia_f <= 7 then
                    set es_festivo = true;
                end if;
                
                if mes_f = 3 and dia_f >= 15 and dia_f <= 21 then
                    set es_festivo = true;
                end if;
                
                if mes_f = 11 and dia_f >= 15 and dia_f <= 21 then
                    set es_festivo = true;
                end if;
            end if;
            
            if not es_festivo then
                select count(*) > 0 into es_festivo 
                from dias_inhabiles 
                where fecha = fecha_temp;
            end if;

            if not es_festivo then
                set dias = dias + 1;
            end if;
        end if;
    end while;
    
    return fecha_temp;
end$$

DELIMITER ;

