--
-- Disparadores `registros`
--
DELIMITER $$
CREATE TRIGGER `tg_generar_num_consecutivo` BEFORE INSERT ON `registros` FOR EACH ROW begin
    declare v_anio int;
    declare v_ultimo_consecutivo varchar(50);
    declare v_siguiente_num int;
    
    set v_anio = year(current_date);
    
    select num_consecutivo into v_ultimo_consecutivo
    from registros
    where num_consecutivo like concat('aeeh-', v_anio, '-%')
    order by id_registro desc
    limit 1;
    
    if v_ultimo_consecutivo is null then
        set v_siguiente_num = 1;
    else
        set v_siguiente_num = cast(substring_index(v_ultimo_consecutivo, '-', -1) as unsigned) + 1;
    end if;
      
    set new.num_consecutivo = concat('aeeh-', v_anio, '-', lpad(v_siguiente_num, 5, '0'));
end
$$
DELIMITER ;

