--
-- Disparadores `seguimiento`
--
DELIMITER $$
CREATE TRIGGER `trg_seguimiento_fecha_limite` BEFORE INSERT ON `seguimiento` FOR EACH ROW begin
    declare v_dias int;
    
    select dias_atencion into v_dias
    from turno
    where id_registro = new.id_registro
    limit 1;
    
    if v_dias is not null then
        set new.fecha_limite = fn_dias_habiles(new.fecha_inicio, v_dias);
    end if;
end
$$
DELIMITER ;

