--
-- Estructura para la vista `v_beneficiarios_directos_mensual`
--
DROP TABLE IF EXISTS `v_beneficiarios_directos_mensual`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_beneficiarios_directos_mensual`  AS SELECT month(`r`.`fecha_captura`) AS `mes`, coalesce(sum(`s`.`beneficiarios_directos`),0) AS `total_directos` FROM (`registros` `r` join `seguimiento` `s` on(`r`.`id_registro` = `s`.`id_registro`)) GROUP BY month(`r`.`fecha_captura`) ORDER BY coalesce(sum(`s`.`beneficiarios_directos`),0) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_beneficiarios_indirectos_mensual`
--
DROP TABLE IF EXISTS `v_beneficiarios_indirectos_mensual`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_beneficiarios_indirectos_mensual`  AS SELECT month(`r`.`fecha_captura`) AS `mes`, coalesce(sum(`s`.`beneficiarios_indirectos`),0) AS `total_indirectos` FROM (`registros` `r` join `seguimiento` `s` on(`r`.`id_registro` = `s`.`id_registro`)) GROUP BY month(`r`.`fecha_captura`) ORDER BY coalesce(sum(`s`.`beneficiarios_indirectos`),0) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_cobertura_municipal`
--
DROP TABLE IF EXISTS `v_cobertura_municipal`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_cobertura_municipal`  AS SELECT count(`m`.`id_municipio`) AS `total_municipios`, sum(case when `t`.`total_solicitudes` > 0 then 1 else 0 end) AS `municipios_con_solicitud`, sum(case when coalesce(`t`.`total_solicitudes`,0) = 0 then 1 else 0 end) AS `municipios_sin_solicitud`, round(sum(case when `t`.`total_solicitudes` > 0 then 1 else 0 end) / count(`m`.`id_municipio`) * 100,1) AS `porcentaje_cobertura` FROM (`municipio` `m` left join (select `registros`.`id_municipio` AS `id_municipio`,count(`registros`.`id_registro`) AS `total_solicitudes` from `registros` group by `registros`.`id_municipio`) `t` on(`m`.`id_municipio` = `t`.`id_municipio`)) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_comportamiento_mensual`
--
DROP TABLE IF EXISTS `v_comportamiento_mensual`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_comportamiento_mensual`  AS SELECT month(`registros`.`fecha_captura`) AS `mes`, count(`registros`.`id_registro`) AS `total_solicitudes` FROM `registros` GROUP BY month(`registros`.`fecha_captura`) ORDER BY count(`registros`.`id_registro`) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_grafica_clasificacion`
--
DROP TABLE IF EXISTS `v_grafica_clasificacion`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_grafica_clasificacion`  AS SELECT CASE WHEN `ts`.`nombre_tipo` in ('expos','congresos','capacitaciones','ferias','foros','ponencias','talleres','reuniones de trabajo') THEN 'invitaciones' ELSE `ts`.`nombre_tipo` END AS `clasificacion`, count(`r`.`id_registro`) AS `total_solicitudes` FROM (`tipo_solicitud` `ts` left join `registros` `r` on(`ts`.`id_tipo_sol` = `r`.`id_tipo_sol`)) GROUP BY CASE WHEN `ts`.`nombre_tipo` in ('expos','congresos','capacitaciones','ferias','foros','ponencias','talleres','reuniones de trabajo') THEN 'invitaciones' ELSE `ts`.`nombre_tipo` END ORDER BY sum(case when `r`.`id_registro` is not null then 1 else 0 end) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_grafica_origen_solicitud`
--
DROP TABLE IF EXISTS `v_grafica_origen_solicitud`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_grafica_origen_solicitud`  AS SELECT CASE WHEN `registros`.`gestion_atencion_pueblo` = 1 THEN 'atencion al pueblo' ELSE 'otras instancias' END AS `origen_solicitud`, count(`registros`.`id_registro`) AS `total_solicitudes`, round(count(`registros`.`id_registro`) / (select count(0) from `registros`) * 100,1) AS `porcentaje` FROM `registros` GROUP BY `registros`.`gestion_atencion_pueblo` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_grafica_solicitudes_ingresadas`
--
DROP TABLE IF EXISTS `v_grafica_solicitudes_ingresadas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_grafica_solicitudes_ingresadas`  AS SELECT year(`r`.`fecha_captura`) AS `anio`, month(`r`.`fecha_captura`) AS `mes`, count(`r`.`id_registro`) AS `recibidas`, sum(case when `s`.`id_etapa` = 5 then 1 else 0 end) AS `atendidas`, sum(case when `s`.`id_etapa` in (6,7) then 1 else 0 end) AS `en_proceso` FROM (`registros` `r` left join `seguimiento` `s` on(`s`.`id_registro` = `r`.`id_registro`)) GROUP BY year(`r`.`fecha_captura`), month(`r`.`fecha_captura`) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_grafica_solicitudes_por_municipio`
--
DROP TABLE IF EXISTS `v_grafica_solicitudes_por_municipio`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_grafica_solicitudes_por_municipio`  AS SELECT `m`.`nombre_municipio` AS `municipio`, count(`r`.`id_registro`) AS `total_solicitudes` FROM (`municipio` `m` left join `registros` `r` on(`m`.`id_municipio` = `r`.`id_municipio`)) GROUP BY `m`.`id_municipio`, `m`.`nombre_municipio` ORDER BY count(`r`.`id_registro`) DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_impacto_social_beneficiarios`
--
DROP TABLE IF EXISTS `v_impacto_social_beneficiarios`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_impacto_social_beneficiarios`  AS SELECT coalesce(sum(`s`.`beneficiarios_directos`),0) AS `total_beneficiarios_directos`, coalesce(sum(`s`.`beneficiarios_indirectos`),0) AS `total_beneficiarios_indirectos` FROM `seguimiento` AS `s` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_lista_expedientes`
--
DROP TABLE IF EXISTS `v_lista_expedientes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_lista_expedientes`  AS SELECT `ex`.`id_expediente` AS `id_expediente`, `r`.`id_registro` AS `id_registro`, `ex`.`no_expediente_fisico` AS `no_expediente_fisico`, `ex`.`fecha_apertura` AS `fecha_apertura`, `ex`.`fecha_cierre` AS `fecha_cierre`, `r`.`num_consecutivo` AS `numero_consecutivo`, `r`.`num_oficio` AS `numero_oficio`, `r`.`num_turno` AS `numero_turno_aeeh`, `r`.`asunto` AS `asunto`, `r`.`nom_remitente` AS `remitente`, `et`.`tipo_entidad` AS `enviado_a`, `t`.`tipo` AS `prioridad`, group_concat(concat(`u`.`nombre`,' ',`u`.`apellido_paterno`,' ',coalesce(`u`.`apellido_materno`,'')) separator ', ') AS `turnado_a`, coalesce(`e`.`nombre_est`,'turnado') AS `estatus_oficio`, cast(`r`.`fecha_captura` as date) AS `fecha_captura`, coalesce(`s`.`fecha_limite`,`fn_dias_habiles`(`t`.`fecha_turno`,`t`.`dias_atencion`)) AS `fecha_limite`, `ts`.`nombre_tipo` AS `tipo_solicitud` FROM (((((((`expediente` `ex` join `registros` `r` on(`ex`.`id_registro` = `r`.`id_registro`)) left join `tipo_solicitud` `ts` on(`ts`.`id_tipo_sol` = `r`.`id_tipo_sol`)) left join `turno` `t` on(`t`.`id_registro` = `r`.`id_registro`)) left join `usuario` `u` on(`u`.`id_usuario` = `t`.`id_usuario`)) left join `seguimiento` `s` on(`s`.`id_registro` = `r`.`id_registro`)) left join `etapa` `e` on(`e`.`id_etapa` = `s`.`id_etapa`)) left join `entidad_turno` `et` on(`et`.`id_registro` = `r`.`id_registro`)) GROUP BY `ex`.`id_expediente`, `r`.`id_registro` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_lista_seguimiento`
--
DROP TABLE IF EXISTS `v_lista_seguimiento`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_lista_seguimiento`  AS SELECT `s`.`id_seguimiento` AS `id_seguimiento`, `r`.`id_registro` AS `id_registro`, `r`.`num_consecutivo` AS `num_consecutivo`, `r`.`num_oficio` AS `num_oficio`, `r`.`num_turno` AS `numero_turno_aeeh`, `r`.`asunto` AS `asunto`, `r`.`nom_remitente` AS `nombre_remitente`, `et`.`tipo_entidad` AS `enviado_a`, `t`.`tipo` AS `prioridad`, concat(`u`.`nombre`,' ',`u`.`apellido_paterno`,' ',coalesce(`u`.`apellido_materno`,'')) AS `turnado_a`, coalesce(`e`.`nombre_est`,'turnado') AS `estatus_oficio`, cast(`r`.`fecha_captura` as date) AS `fecha_captura`, coalesce(`s`.`fecha_limite`,`fn_dias_habiles`(`t`.`fecha_turno`,`t`.`dias_atencion`)) AS `fecha_limite`, coalesce(`s`.`recibido`,0) AS `recibido`, `t`.`id_usuario` AS `id_usuario_asignado`, CASE WHEN lcase(coalesce(`e`.`nombre_est`,'turnado')) in ('atendido','cerrado') THEN 'cumplido' WHEN curdate() > coalesce(`s`.`fecha_limite`,`fn_dias_habiles`(`t`.`fecha_turno`,`t`.`dias_atencion`)) THEN 'vencido' WHEN to_days(coalesce(`s`.`fecha_limite`,`fn_dias_habiles`(`t`.`fecha_turno`,`t`.`dias_atencion`))) - to_days(curdate()) <= 2 THEN 'por vencer' ELSE 'a tiempo' END AS `estatus_sla` FROM (((((`turno` `t` join `registros` `r` on(`t`.`id_registro` = `r`.`id_registro`)) join `usuario` `u` on(`u`.`id_usuario` = `t`.`id_usuario`)) left join `seguimiento` `s` on(`s`.`id_registro` = `r`.`id_registro`)) left join `etapa` `e` on(`e`.`id_etapa` = `s`.`id_etapa`)) left join `entidad_turno` `et` on(`et`.`id_registro` = `r`.`id_registro`)) ;

